sp_widget.client_script:
api.controller = function(spModal, spUtil) {
  var c = this;

  c.tab = 'overview';

  c.form = {
    score:    c.data.score      || '',
    comments: c.data.work_notes || ''
  };

  c.newNote    = '';
  c.saving     = false;
  c.addingNote = false;
  c.rejecting  = false;
  c.error      = '';

  // ── VISIBILITY FLAGS ──
  c.isCompleted = (c.data.status === 'Review completed');
  c.canScore    = !c.isCompleted && c.data.is_last_reviewer;
  c.isReadOnly  = !c.isCompleted && !c.data.is_last_reviewer && !c.data.submitted;

  // ── FORMAT FILE SIZE ──
  c.formatSize = function(bytes) {
    if (!bytes) return '';
    return (parseInt(bytes) / 1024).toFixed(2) + ' KB';
  };

  // ── SUBMIT / PROCEED ──
  c.submit = function() {
    if (!c.data.found) {
      c.error = 'No record found.';
      return;
    }

    if (c.canScore && !c.form.score) {
      c.error = 'Please select a score before submitting.';
      return;
    }

    c.saving = true;
    c.error  = '';

    c.data.action = 'submit_review';
    c.data.form   = angular.copy(c.form);

    c.server.update().then(function() {
      c.saving = false;

      if (c.data.success) {
        var msg = c.data.last_reviewer
          ? 'Review completed! All groups have finished reviewing.'
          : 'Review submitted! Assigned to next group: ' + (c.data.next_group || '');

        spModal.alert(msg).then(function() {
          spUtil.navigate('review');
        });
      } else {
        c.error = c.data.error || 'An unexpected server error occurred.';
      }
    });
  };

  // ── ADD WORK NOTE ──
  c.addNote = function() {
    if (!c.newNote || !c.newNote.trim()) return;

    c.addingNote = true;
    c.error      = '';

    c.data.action = 'add_note';
    c.data.form   = { comments: c.newNote };

    c.server.update().then(function() {
      c.addingNote = false;

      if (c.data.success) {
        c.newNote = '';
        spModal.alert('Work note added successfully!');
      } else {
        c.error = c.data.error || 'Failed to add note.';
      }
    });
  };

  // ── REJECT REVIEW ──
  c.rejectReview = function() {
    spModal.confirm('Are you sure you want to decline this review? This cannot be undone.')
      .then(function(confirmed) {
        if (!confirmed) return;

        c.rejecting   = true;
        c.error       = '';
        c.data.action = 'reject_review';

        c.server.update().then(function() {
          c.rejecting = false;

          if (c.data.success) {
            c.data.status = 'Declined by Reviewer';
            c.isCompleted = true;
            c.canScore    = false;
            c.isReadOnly  = false;

            spModal.alert('Review declined successfully.').then(function() {
              spUtil.navigate('review');
            });
          } else {
            c.error = c.data.error || 'Failed to decline the review.';
          }
        });
      });
  };

};

sp_widget.css:
/* =========================================================
   GATENOW · PROPOSAL REVIEW
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   ── THE IDEA ──────────────────────────────────────────────

   A reviewer is here to read and then judge. So the middle of
   the page is a document, not a grid of cards, and the two
   rails either side of it are chrome: a table of contents and
   the instrument for recording a decision.

   That split is what the whole stylesheet is built on. The
   document column has no card, no border, no shadow — it is
   paper. Everything that is interface sits on a rail, divided
   from the paper by a single hairline. One radius family for
   controls, none at all for structure.

   ── TWO VOICES ────────────────────────────────────────────

   Outfit for everything the system says: labels, controls,
   navigation, figures.

   A serif for everything the applicant wrote. Four hundred
   words of narrative in a UI sans is a wall; in a serif at a
   66-character measure it is a document. It also draws the
   line that matters most on this page — between what somebody
   submitted and what the system is telling you about it.

   No font file: the serif is a system stack, so it costs
   nothing and cannot fail to load.

   ── WHAT WAS CUT ──────────────────────────────────────────

   Tracked-out capital labels above every field. Meta strings
   strung together with middle dots. Eight card accent colours
   that encoded which card you were looking at rather than what
   was in it. An entrance animation on every section. All of it
   was decoration wearing the clothes of structure.

   Colour now appears in three places and nowhere else: the
   score band, the review state, and the single blue used for
   anything clickable.
   ========================================================= */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- palette ----------
   Six values and three signals. The navy and the blue are the
   portal's own, so this page belongs to the same product as
   the queue it was opened from.
   ------------------------------------------------------- */

$ink:   #0a2540;
$ink-2: #3a4a60;
$ink-3: #6b7a90;
$ink-4: #98a2b3;

$rule:   #e4e9f0;
$rule-2: #f0f3f8;
$wash:   #f7f9fc;
$paper:  #ffffff;
$ground: #f4f6fb;

$blue:    #1560e0;
$blue-dk: #0f4cbb;
$blue-1:  #eef4fe;

/* the three score bands, at the 7 and 4 thresholds the
   template already used */
$high: #1f7a5c;
$mid:  #9a6b18;
$low:  #ab3243;

$ui:    "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;
/* Georgia is the one serif present on effectively every
   machine; the others ahead of it are better where they exist */
$serif: "Iowan Old Style", "Palatino Linotype", Palatino, Charter, Georgia, "Times New Roman", serif;

$ease: cubic-bezier(0.32, 0.72, 0, 1);


/* =========================================================
   FRAME
   ========================================================= */

.panel,
.panel-body,
.sp-widget {
  overflow: visible !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
}

.pr {
  min-height: 100vh;
  background: $ground;
  font-family: $ui;
  color: $ink;
  -webkit-font-smoothing: antialiased;
}

.pr *,
.pr *::before,
.pr *::after { box-sizing: border-box; }


/* =========================================================
   THE BAR

   Sticky, 60px, one hairline under it. Identity left, decision
   right. Nothing else earns a place at the top of every scroll
   position.
   ========================================================= */

.pr-bar {
  position: sticky;
  top: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  height: 60px;
  padding: 0 24px;
  border-bottom: 1px solid $rule;
  background: rgba(255, 255, 255, 0.94);
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
}

.pr-bar__id {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.pr-bar__back {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border-radius: 8px;
  color: $ink-3;
  text-decoration: none;
  transition: background 0.2s $ease, color 0.2s $ease;
}

.pr-bar__back:hover,
.pr-bar__back:focus {
  background: $wash;
  color: $ink;
  text-decoration: none;
}

.pr-bar__num {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.01em;
  font-variant-numeric: tabular-nums;
  color: $ink;
  white-space: nowrap;
}

/* sentence case, not a tracked-out capital chip. The status
   is a phrase a person reads, not a code they decode. */
.pr-state {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 13.5px;
  font-weight: 500;
  white-space: nowrap;
}

.pr-state::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.pr-state--live { color: $blue-dk; }
.pr-state--done { color: $high; }
.pr-state--hold { color: $mid; }
.pr-state--stop { color: $low; }

.pr-bar__group {
  font-size: 13.5px;
  color: $ink-4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pr-bar__act {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.pr-bar__score {
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding-right: 14px;
  margin-right: 4px;
  border-right: 1px solid $rule;
}

.pr-bar__score-n {
  font-size: 19px;
  font-weight: 700;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
  color: $ink;
}

.pr-bar__score-d {
  font-size: 13px;
  color: $ink-4;
}


/* =========================================================
   THE ONE LINE

   Which of these shows is the only thing that explains why the
   score panel behaves the way it does for this reader, so it
   is a sentence rather than a badge.
   ========================================================= */

.pr-say {
  padding: 13px 24px;
  border-bottom: 1px solid $rule;
  background: $blue-1;
  font-size: 14px;
  line-height: 1.6;
  color: $ink-2;
}

.pr-say strong {
  font-weight: 600;
  color: $ink;
}

.pr-say--done {
  background: #eef6f2;
}


/* =========================================================
   LAYOUT

   Three columns divided by hairlines. The rules are the
   structure: no card, no shadow, no gap to imply separation
   that a line states outright.
   ========================================================= */

.pr-frame {
  display: grid;
  grid-template-columns: 212px minmax(0, 1fr) 320px;
  align-items: start;
  min-height: calc(100vh - 60px);
  background: $paper;
}


/* ---------- contents ---------- */

.pr-toc {
  position: sticky;
  top: 60px;
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 22px 12px;
  border-right: 1px solid $rule;
  background: $wash;
  min-height: calc(100vh - 60px);
}

.pr-toc__item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 12px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  font-family: inherit;
  font-size: 15px;
  font-weight: 400;
  text-align: left;
  color: $ink-2;
  cursor: pointer;
  transition: background 0.18s $ease, color 0.18s $ease;
}

.pr-toc__item:hover {
  background: rgba(10, 37, 64, 0.045);
  color: $ink;
}

/* the current section is stated by weight and ink, not by a
   filled pill. On a rail of five items a fill is louder than
   the distinction warrants. */
.pr-toc__item.is-on {
  background: $paper;
  box-shadow: inset 2px 0 0 $blue;
  color: $ink;
  font-weight: 600;
}

.pr-toc__n {
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  color: $ink-4;
}


/* ---------- the document ---------- */

.pr-doc {
  padding: 44px 56px 88px;
  min-width: 0;
  background: $paper;
}

.pr .pr-doc__title {
  margin: 0;
  max-width: 24ch;
  font-family: $ui;
  font-size: 32px;
  font-weight: 700;
  line-height: 1.16;
  letter-spacing: -0.024em;
  color: $ink;
}

.pr .pr-doc__by {
  margin: 12px 0 0;
  font-size: 15px;
  color: $ink-3;
}


/* the sum being asked for. One large figure, because it is the
   number a reviewer holds in their head through everything
   else they read. */
.pr-ask {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 22px 0 20px;
  margin-top: 26px;
  border-top: 1px solid $rule;
}

.pr-ask__n {
  font-size: 30px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  color: $ink;
}

.pr-ask__l {
  font-size: 15px;
  color: $ink-3;
}


/* ---------- the facts strip ----------
   A short table rather than a string of values joined by
   middle dots. Each value keeps the label that makes it
   meaningful, and the eye can find one without reading all.
   ------------------------------------------------------- */

.pr .pr-facts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0;
  margin: 0 0 8px;
  padding: 0;
  border-top: 1px solid $rule-2;
  border-left: 1px solid $rule-2;
}

.pr-fact {
  padding: 13px 16px;
  border-right: 1px solid $rule-2;
  border-bottom: 1px solid $rule-2;
  min-width: 0;
}

.pr .pr-fact dt {
  margin: 0 0 4px;
  font-size: 13px;
  font-weight: 400;
  color: $ink-4;
}

.pr .pr-fact dd {
  margin: 0;
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.006em;
  color: $ink;
  word-break: break-word;
}


/* ---------- the prose ----------

   The part of the page that deserves the room. Serif, 17px,
   1.7 leading, and a measure that stops at 66 characters
   whatever the window does.
   ------------------------------------------------------- */

.pr-read {
  padding-top: 34px;
  margin-top: 34px;
  border-top: 1px solid $rule;
}

.pr .pr-read__h {
  margin: 0 0 14px;
  font-family: $ui;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.012em;
  color: $ink;
}

.pr .pr-read__p {
  margin: 0;
  max-width: 66ch;
  font-family: $serif;
  font-size: 17px;
  font-weight: 400;
  line-height: 1.7;
  color: #253449;
  /* the line breaks the applicant typed are theirs to keep */
  white-space: pre-line;
}


/* ---------- field sets ---------- */

.pr-set {
  padding-top: 30px;
  margin-top: 30px;
  border-top: 1px solid $rule;
}

.pr .pr-set__h {
  margin: 0 0 16px;
  font-family: $ui;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.012em;
  color: $ink;
}

.pr .pr-pairs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 40px;
  margin: 0;
  padding: 0;
  max-width: 78ch;
}

.pr-pair {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 20px;
  padding: 11px 0;
  border-bottom: 1px solid $rule-2;
  min-width: 0;
}

.pr .pr-pair dt {
  margin: 0;
  flex-shrink: 0;
  font-size: 14px;
  font-weight: 400;
  color: $ink-4;
}

.pr .pr-pair dd {
  margin: 0;
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.006em;
  text-align: right;
  color: $ink;
  word-break: break-word;
}

/* SSN and TIN. Set in a way that makes a screenshot of this
   block obviously a different kind of thing from a screenshot
   of an address. */
.pr .pr-pair--held dd {
  padding: 2px 9px;
  border: 1px solid $rule;
  border-radius: 5px;
  background: $wash;
  font-variant-numeric: tabular-nums;
  color: $ink-2;
}

.pr-link {
  color: $blue-dk;
  text-decoration: none;
  border-bottom: 1px solid rgba(21, 96, 224, 0.3);
}

.pr-link:hover,
.pr-link:focus {
  color: $blue;
  border-bottom-color: $blue;
  text-decoration: none;
}

.pr .pr-none {
  margin: 20px 0 0;
  font-size: 15px;
  color: $ink-4;
}


/* ---------- files ----------
   A list, not a grid of tiles. Downloading a file is a
   one-line task and a tile is three lines of chrome around it.
   ------------------------------------------------------- */

.pr .pr-files {
  margin: 0;
  padding: 0;
  list-style: none;
  max-width: 72ch;
  border-top: 1px solid $rule-2;
}

.pr-file {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 13px 4px;
  border-bottom: 1px solid $rule-2;
}

.pr-file__name {
  flex: 1;
  min-width: 0;
  font-size: 15px;
  color: $ink;
  word-break: break-word;
}

.pr-file__size {
  flex-shrink: 0;
  font-size: 13.5px;
  font-variant-numeric: tabular-nums;
  color: $ink-4;
}

.pr-file__get {
  flex-shrink: 0;
  font-size: 14px;
  font-weight: 500;
  color: $blue-dk;
  text-decoration: none;
}

.pr-file__get:hover,
.pr-file__get:focus {
  color: $blue;
  text-decoration: underline;
}


/* ---------- notes ---------- */

.pr-write {
  max-width: 72ch;
  margin-top: 28px;
}

.pr-write__box {
  width: 100%;
  padding: 14px 16px;
  border: 1px solid $rule;
  border-radius: 10px;
  background: $paper;
  font-family: $ui;
  font-size: 15px;
  line-height: 1.6;
  color: $ink;
  resize: vertical;
  transition: border-color 0.2s $ease, box-shadow 0.2s $ease;
}

.pr-write__box:focus {
  outline: 0;
  border-color: rgba(21, 96, 224, 0.5);
  box-shadow: 0 0 0 3px $blue-1;
}

.pr-write__box::placeholder { color: $ink-4; }

.pr-write__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 12px;
}

.pr-write__count {
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  color: $ink-4;
}

.pr .pr-thread {
  margin: 36px 0 0;
  padding: 0;
  list-style: none;
  max-width: 72ch;
}

/* posts are separated by space and a rule, not boxed. A thread
   of five boxes reads as five unrelated things. */
.pr-post {
  padding: 20px 0;
  border-top: 1px solid $rule-2;
}

.pr-post__who {
  font-size: 14px;
  font-weight: 600;
  color: $ink;
}

.pr-post__when {
  margin-left: 10px;
  font-size: 13px;
  color: $ink-4;
}

.pr .pr-post__text {
  margin: 8px 0 0;
  max-width: 64ch;
  font-family: $serif;
  font-size: 16px;
  line-height: 1.65;
  color: #253449;
  white-space: pre-line;
}


/* =========================================================
   THE DECISION RAIL

   Fixed beside the reading. A reviewer forms a judgement while
   reading a particular paragraph, and the control to record it
   should be within reach at that moment rather than five
   scrolls away.
   ========================================================= */

.pr-side {
  position: sticky;
  top: 60px;
  border-left: 1px solid $rule;
  background: $wash;
  min-height: calc(100vh - 60px);
}

.pr-side__stick { padding: 24px 22px; }

.pr .pr-side__h {
  margin: 0 0 20px;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.012em;
  color: $ink;
}

.pr .pr-side__note {
  margin: 16px 0 0;
  font-size: 14px;
  line-height: 1.6;
  color: $ink-3;
}


/* ---------- the scale ----------

   The one bold element on the page. Ten cells, two rows of
   five, numbers only. It is the instrument the whole screen
   exists to operate, so it is allowed to be the thing you
   notice.
   ------------------------------------------------------- */

.pr-scale {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
}

.pr-scale__n {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 50px;
  padding: 0;
  border: 1px solid $rule;
  border-radius: 9px;
  background: $paper;
  font-family: $ui;
  font-size: 17px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  color: $ink-2;
  cursor: pointer;
  transition: border-color 0.16s $ease, background 0.16s $ease, color 0.16s $ease;
}

.pr-scale__n:hover {
  border-color: rgba(21, 96, 224, 0.45);
  color: $ink;
}

/* the chosen number is the only filled thing in the rail */
.pr-scale__n.is-on {
  border-color: $ink;
  background: $ink;
  color: $paper;
  font-weight: 600;
}

.pr-scale__n.is-on.is-high { border-color: $high; background: $high; }
.pr-scale__n.is-on.is-mid  { border-color: $mid;  background: $mid; }
.pr-scale__n.is-on.is-low  { border-color: $low;  background: $low; }

/* an earlier group sees the instrument without being able to
   touch it, so they know what the final group will use */
.pr-scale--off .pr-scale__n {
  background: transparent;
  border-color: $rule-2;
  color: $ink-4;
  cursor: default;
}

.pr .pr-scale__ends {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 10px 0 0;
  font-size: 13px;
  color: $ink-4;
}

/* a sentence, not a badge. "A strong proposal, at 8 out of 10"
   is what the reviewer would say out loud. */
.pr .pr-verdict {
  margin: 18px 0 0;
  padding-top: 16px;
  border-top: 1px solid $rule;
  font-size: 14.5px;
  line-height: 1.55;
  font-weight: 500;
}

.pr-verdict--high { color: $high; }
.pr-verdict--mid  { color: $mid; }
.pr-verdict--low  { color: $low; }


/* ---------- the settled score ---------- */

.pr-final {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 20px 22px;
  border: 1px solid $rule;
  border-radius: 12px;
  background: $paper;
}

.pr-final__n {
  font-size: 40px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.04em;
  font-variant-numeric: tabular-nums;
  color: $ink;
}

.pr-final__d {
  font-size: 14px;
  color: $ink-4;
}

.pr-final--high .pr-final__n { color: $high; }
.pr-final--mid .pr-final__n  { color: $mid; }
.pr-final--low .pr-final__n  { color: $low; }

.pr-final--none .pr-final__n { color: $ink-4; }

.pr-err {
  margin-top: 18px;
  padding: 12px 14px;
  border: 1px solid #edc9cf;
  border-radius: 9px;
  background: #fdf3f4;
  font-size: 14px;
  line-height: 1.55;
  color: $low;
}


/* =========================================================
   CONTROLS

   Two buttons, one shape. Submit is filled because it is the
   thing the page is for; Decline is not, because a filled red
   beside a filled blue is a coin toss at speed and this one
   cannot be undone.
   ========================================================= */

.pr-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 36px;
  padding: 0 16px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  font-family: $ui;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.2s $ease, border-color 0.2s $ease, color 0.2s $ease;
}

.pr-btn--sm {
  height: 34px;
  font-size: 13.5px;
}

.pr-btn--go {
  background: $blue;
  border-color: $blue;
  color: $paper;
  font-weight: 600;
}

.pr-btn--go:hover,
.pr-btn--go:focus {
  background: $blue-dk;
  border-color: $blue-dk;
  color: $paper;
  text-decoration: none;
}

.pr-btn--quiet { color: $ink-3; }

.pr-btn--quiet:hover,
.pr-btn--quiet:focus {
  background: #fdf3f4;
  color: $low;
  text-decoration: none;
}

.pr-btn--ghost {
  border-color: $rule;
  color: $ink-2;
}

.pr-btn--ghost:hover,
.pr-btn--ghost:focus {
  border-color: $ink-4;
  color: $ink;
  text-decoration: none;
}

.pr-btn:disabled {
  opacity: 0.4;
  cursor: default;
}

.pr-btn--go:disabled:hover {
  background: $blue;
  border-color: $blue;
}

.pr-btn:focus-visible,
.pr-toc__item:focus-visible,
.pr-scale__n:focus-visible,
.pr-bar__back:focus-visible,
.pr-file__get:focus-visible,
.pr-link:focus-visible {
  outline: 2px solid $blue;
  outline-offset: 2px;
}


/* =========================================================
   NO ACCESS

   An explanation and a way forward, in the interface's voice.
   Not an apology and not a lock icon.
   ========================================================= */

.pr-gate {
  max-width: 46ch;
  margin: 0 auto;
  padding: 120px 24px;
}

.pr .pr-gate__title {
  margin: 0;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.024em;
  color: $ink;
}

.pr .pr-gate__text {
  margin: 14px 0 26px;
  font-family: $serif;
  font-size: 17px;
  line-height: 1.65;
  color: #253449;
}


/* =========================================================
   MOTION

   One moment, at load, and then nothing that moves unless
   somebody moved it. The transitions above answer an action —
   a hover, a focus, a number being chosen — which is the only
   kind of motion this page has any use for.
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes prIn {
    from { opacity: 0; }
    to   { opacity: 1; }
  }

  .pr-frame { animation: prIn 0.4s $ease; }
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1180px) {

  /* the decision rail drops under the document rather than
     squeezing the measure. Reading width is the one thing on
     this page that must not be negotiated away. */
  .pr-frame { grid-template-columns: 200px minmax(0, 1fr); }

  .pr-doc { padding: 40px 40px 40px; }

  .pr-side {
    grid-column: 1 / -1;
    position: static;
    min-height: 0;
    border-left: 0;
    border-top: 1px solid $rule;
  }

  .pr-side__stick {
    max-width: 640px;
    padding: 28px 40px 60px;
  }

  .pr-scale { grid-template-columns: repeat(10, minmax(0, 1fr)); }
}

@media (max-width: 860px) {

  .pr-frame { grid-template-columns: minmax(0, 1fr); }

  /* the contents rail becomes a strip above the document */
  .pr-toc {
    position: static;
    flex-direction: row;
    gap: 4px;
    min-height: 0;
    padding: 10px 16px;
    border-right: 0;
    border-bottom: 1px solid $rule;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .pr-toc__item {
    flex-shrink: 0;
    font-size: 14.5px;
  }

  .pr-toc__item.is-on {
    box-shadow: inset 0 -2px 0 $blue;
    background: transparent;
  }

  .pr-doc { padding: 32px 22px 40px; }

  .pr .pr-doc__title { font-size: 26px; }

  .pr .pr-facts { grid-template-columns: repeat(2, minmax(0, 1fr)); }

  .pr .pr-pairs { grid-template-columns: minmax(0, 1fr); }

  .pr-side__stick { padding: 26px 22px 56px; }
}

@media (max-width: 620px) {

  .pr-bar {
    height: auto;
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
    padding: 12px 16px;
  }

  .pr-bar__act { width: 100%; }

  .pr-bar__act .pr-btn { flex: 1; }

  .pr-say { padding: 12px 16px; }

  .pr .pr-facts { grid-template-columns: minmax(0, 1fr); }

  /* ten cells across 320px is 26px each, under the touch
     target minimum, so the scale goes back to two rows */
  .pr-scale { grid-template-columns: repeat(5, minmax(0, 1fr)); }
}

@media (prefers-reduced-motion: reduce) {
  .pr,
  .pr * {
    transition: none;
    animation: none;
  }
}

sp_widget.script:
(function() {
    data.found = false;
    data.success = false;
    data.error = '';
    data.submitted = false;
    data.last_reviewer = false;
    data.is_last_reviewer = false;

    var userId = gs.getUserID();

    // ── GET CURRENT USER'S GROUPS ──
    var userGroups = [];
    var groupMemberGR = new GlideRecordSecure('sys_user_grmember');
    groupMemberGR.addQuery('user', userId);
    groupMemberGR.query();
    while (groupMemberGR.next()) {
        userGroups.push(groupMemberGR.getValue('group'));
    }

    var sysId = $sp.getParameter('sys_id');
    if (!sysId) return;

    var reviewRecordGR = new GlideRecordSecure('x_enno_gatenow_grant_review');
    if (!reviewRecordGR.get(sysId)) return;

    // ── ACCESS GUARD ──
    var isCurrentlyAssigned = userGroups.indexOf(reviewRecordGR.getValue('review_group')) !== -1;
    var reviewerRaw = reviewRecordGR.getValue('reviewer') || '';
    var isPartOfReview = false;

    for (var g = 0; g < userGroups.length; g++) {
        if (reviewerRaw.indexOf(userGroups[g]) !== -1) {
            isPartOfReview = true;
            break;
        }
    }

    if (!isCurrentlyAssigned && !isPartOfReview) return;

    // ── HANDLE ADD WORK NOTE ──
    if (input && input.action === 'add_note' && input.form) {
        if (input.form.comments) {
            reviewRecordGR.work_notes = input.form.comments;
            reviewRecordGR.update();
        }
        data.found = true;
        data.success = true;
    }

    // ── HANDLE REJECT ──
    if (input && input.action === 'reject_review') {
        var currentStatus = (reviewRecordGR.getValue('status') || '').toString().trim();

        if (currentStatus === 'Declined by Reviewer') {
            data.found = true;
            data.success = false;
            data.error = 'This review has already been declined.';
            return;
        }
        if (currentStatus === 'Review completed') {
            data.found = true;
            data.success = false;
            data.error = 'Cannot decline a completed review.';
            return;
        }

        reviewRecordGR.setValue('status', 'Declined by Reviewer');
        reviewRecordGR.update();
        data.found = true;
        data.success = true;
        return;
    }

    // ── HANDLE SUBMIT ──
    if (input && input.action === 'submit_review' && input.form) {
        var form = input.form;
        var groupListRaw = reviewRecordGR.getValue('reviewer') || '';
        var groupArray = groupListRaw.split(',').map(function(s) {
            return s.trim();
        }).filter(function(s) { return s !== ''; });

        var currentGroupSysId = reviewRecordGR.getValue('review_group');
        var currentIndex = groupArray.indexOf(currentGroupSysId);
        var nextIndex = currentIndex + 1;

        if (form.comments) reviewRecordGR.work_notes = form.comments;

        if (currentIndex === -1 || nextIndex >= groupArray.length) {
            // LAST GROUP
            if (form.score) reviewRecordGR.setValue('score', parseInt(form.score, 10));
            reviewRecordGR.setValue('status', 'Review completed');
            reviewRecordGR.update();

            data.found = true;
            data.success = true;
            data.submitted = true;
            data.last_reviewer = true;
        } else {
            // NOT LAST — pass to next group
            var nextGroupSysId = groupArray[nextIndex];
            var nextGroupName = '';
            var nextGroupLookupGR = new GlideRecordSecure('sys_user_group');
            if (nextGroupLookupGR.get(nextGroupSysId)) {
                nextGroupName = nextGroupLookupGR.getDisplayValue('name');
            }

            reviewRecordGR.setValue('review_group', nextGroupSysId);
            reviewRecordGR.setValue('status', 'Review in progress');
            reviewRecordGR.update();

            data.found = true;
            data.success = true;
            data.submitted = true;
            data.last_reviewer = false;
            data.next_group = nextGroupName;
        }
    }

    // ── CHECK STATUS ──
    var currentReviewGroup = reviewRecordGR.getValue('review_group');
    var currentReviewStatus = (reviewRecordGR.getValue('status') || '').toString().trim();

    if (currentReviewStatus === 'Review completed' || userGroups.indexOf(currentReviewGroup) === -1) {
        data.submitted = true;
    }

    // ── VISIBILITY CHECK ──
    var fullReviewerListRaw = reviewRecordGR.getValue('reviewer') || '';
    var fullReviewerArray = fullReviewerListRaw.split(',').map(function(s) {
        return s.trim();
    }).filter(function(s) { return s !== ''; });

    var lastGroupInList = fullReviewerArray.length > 0 ? fullReviewerArray[fullReviewerArray.length - 1] : '';
    data.is_last_reviewer = (reviewRecordGR.getValue('review_group') === lastGroupInList) && 
                            (userGroups.indexOf(reviewRecordGR.getValue('review_group')) !== -1);

    // ── LOAD APPLICANT INFO ──
    var applicantId = reviewRecordGR.getValue('applicant');
    var applicantData = {};
    if (applicantId) {
        var applicantGR = new GlideRecordSecure('x_enno_gatenow_service_applicants');
        if (applicantGR.get(applicantId)) {
            applicantData.number = applicantGR.getValue('number') || '';
            applicantData.first_name = applicantGR.getValue('first_name') || '';
            applicantData.middle_name = applicantGR.getValue('middle_name') || '';
            applicantData.last_name = applicantGR.getValue('last_name') || '';
            applicantData.email = applicantGR.getValue('email') || '';
            applicantData.phone = applicantGR.getValue('phone_number') || '';
            applicantData.gender = applicantGR.getDisplayValue('gender') || '';
            applicantData.dob = applicantGR.getDisplayValue('birthdate') || '';
            applicantData.marital_status = applicantGR.getDisplayValue('marital_status') || '';
            applicantData.race = applicantGR.getDisplayValue('race') || '';
            applicantData.ethnicity = applicantGR.getDisplayValue('ethnicity') || '';
            applicantData.education = applicantGR.getDisplayValue('education_level') || '';
            applicantData.military_status = applicantGR.getDisplayValue('military_status') || '';
            applicantData.applicant_type = applicantGR.getDisplayValue('applicant_type') || '';
            applicantData.tribal = applicantGR.getDisplayValue('tribal_affiliation') || '';
            applicantData.citizenship = applicantGR.getDisplayValue('citizenship_status') || '';
            applicantData.identity_type = applicantGR.getDisplayValue('identity_type') || '';
            applicantData.disability = applicantGR.getDisplayValue('disability_status') || '';
            applicantData.ssn = applicantGR.getValue('ssn') || '';
            applicantData.tin = applicantGR.getValue('tin_ein') || '';
            applicantData.uei = applicantGR.getValue('uei') || '';
            applicantData.street = applicantGR.getValue('street') || '';
            applicantData.city = applicantGR.getValue('city') || '';
            applicantData.country = applicantGR.getValue('country') || '';
            applicantData.zip = applicantGR.getValue('zip_postal_code') || '';
            applicantData.organization = applicantGR.getValue('organization') || '';
            applicantData.program_category = applicantGR.getDisplayValue('program_category') || '';
            applicantData.requested_budget = applicantGR.getDisplayValue('requested_budget') || '';
            applicantData.short_desc = applicantGR.getValue('short_description') || '';
            applicantData.proposal_desc = applicantGR.getValue('proposal_description') || '';
            applicantData.goals = applicantGR.getValue('project_goals_and_objectives') || '';
            applicantData.methodology = applicantGR.getValue('project_activities_methodology') || '';
            applicantData.project_start = applicantGR.getDisplayValue('project_start_date') || '';
            applicantData.project_end = applicantGR.getDisplayValue('project_end_date') || '';
            applicantData.submission_date = applicantGR.getDisplayValue('submission_date') || '';
            applicantData.state = applicantGR.getDisplayValue('state') || '';

            var appDocs = [];
            var appAttachmentGR = new GlideRecordSecure('sys_attachment');
            appAttachmentGR.addQuery('table_name', 'x_enno_gatenow_service_applicants');
            appAttachmentGR.addQuery('table_sys_id', applicantGR.getUniqueValue());
            appAttachmentGR.query();
            while (appAttachmentGR.next()) {
                appDocs.push({
                    name: appAttachmentGR.getValue('file_name'),
                    size: appAttachmentGR.getValue('size_bytes'),
                    sys_id: appAttachmentGR.getValue('sys_id'),
                    url: '/sys_attachment.do?sys_id=' + appAttachmentGR.getValue('sys_id')
                });
            }
            applicantData.documents = appDocs;
        }
    }

    // ── LOAD PROGRAM INFO ──
    var programId = reviewRecordGR.getValue('program');
    var programData = {};
    if (programId) {
        var programGR = new GlideRecordSecure('x_enno_gatenow_grant_program');
        if (programGR.get(programId)) {
            programData.name = programGR.getDisplayValue('program_name') || '';
            programData.number = programGR.getValue('number') || '';
            programData.start_date = programGR.getDisplayValue('start_date') || '';
            programData.category = programGR.getDisplayValue('category') || '';
            programData.end_date = programGR.getDisplayValue('end_date') || '';
            programData.status = programGR.getDisplayValue('status') || '';
            programData.budget = programGR.getDisplayValue('program_budget') || '';
            programData.description = programGR.getValue('program_description') || '';
            programData.synopsis = programGR.getValue('synopsis') || '';
            programData.terms = programGR.getValue('terms_and_conditions') || '';
            programData.eligibility = programGR.getValue('eligibility_summary') || '';
            programData.summary_statement = programGR.getValue('summary_statement') || '';

            var progDocs = [];
            var progAttachmentGR = new GlideRecordSecure('sys_attachment');
            progAttachmentGR.addQuery('table_name', 'x_enno_gatenow_grant_program');
            progAttachmentGR.addQuery('table_sys_id', programGR.getUniqueValue());
            progAttachmentGR.query();
            while (progAttachmentGR.next()) {
                progDocs.push({
                    name: progAttachmentGR.getValue('file_name'),
                    size: progAttachmentGR.getValue('size_bytes'),
                    sys_id: progAttachmentGR.getValue('sys_id'),
                    url: '/sys_attachment.do?sys_id=' + progAttachmentGR.getValue('sys_id')
                });
            }
            programData.documents = progDocs;
        }
    }

    // ── LOAD WORK NOTES (Journal) ──
    var workNotesHistory = [];
    var journalGR = new GlideRecordSecure('sys_journal_field');
    journalGR.addQuery('name', 'x_enno_gatenow_grant_review');
    journalGR.addQuery('element', 'work_notes');
    journalGR.addQuery('element_id', reviewRecordGR.getUniqueValue());
    journalGR.orderByDesc('sys_created_on');
    journalGR.query();
    while (journalGR.next()) {
        workNotesHistory.push({
            value: journalGR.getValue('value'),
            created: journalGR.getDisplayValue('sys_created_on'),
            user: journalGR.getDisplayValue('sys_created_by')
        });
    }

    // ── FINAL DATA ASSIGNMENT ──
    data.found = true;
    data.sys_id = reviewRecordGR.getUniqueValue();
    data.number = reviewRecordGR.getValue('number');
    data.review_group = reviewRecordGR.getDisplayValue('review_group');
    data.status = reviewRecordGR.getDisplayValue('status');
    data.score = reviewRecordGR.getValue('score');
    data.work_notes = reviewRecordGR.getValue('work_notes') || '';
    data.work_notes_list = workNotesHistory;
    data.applicant = applicantData;
    data.program = programData;
})();
